{"command": "python3 -c "
import itertools, json, os, subprocess, statistics
best = 0
best_params = None
for lr in [0.01, 0.02, 0.05, 0.1, 0.2]:
    for epochs in [10,15,20,25]:
        for bs in [16,32,64,128]:
            cmd = ['python3','train.py','--n','1200','--positive_rate','0.3','--label_noise','0.05','--split','0.8','--normalize','none','--epochs',str(epochs),'--batch_size',str(bs),'--lr',str(lr),'--lr_schedule','const','--weight_decay','0.0','--class_weight','none','--threshold','0.5','--data_seed','7','--out','/tmp/tmp.json']
            result = subprocess.run(cmd, capture_output=True, text=True)
            out = json.loads(result.stdout.strip())
            acc = out['test_accuracy']
            if acc > best:
                best = acc
                best_params = (lr, epochs, bs)
print('Best acc:', best, 'params:', best_params)
""}

